const JSON_HEADERS={'content-type':'application/json; charset=utf-8','cache-control':'no-store'};
const HTML_HEADERS={
  'content-type':'text/html; charset=utf-8','cache-control':'no-store',
  'content-security-policy':"default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline' https://sandbox.web.squarecdn.com https://web.squarecdn.com https://www.paypal.com https://www.paypalobjects.com; connect-src 'self' https://*.squareup.com https://*.squarecdn.com https://*.paypal.com; frame-src https://*.squareup.com https://*.paypal.com; img-src 'self' data: https://*.paypalobjects.com; frame-ancestors 'self'; base-uri 'self'; form-action 'self'",
  'x-content-type-options':'nosniff','referrer-policy':'strict-origin-when-cross-origin'
};
const MAX_BODY=32_000;
const MAX_METHODS=50;
const MAX_TRANSACTIONS=500;
const SQUARE_VERSION='2026-07-15';
const OWNER_COOKIE='atlas_wallet_owner';
const PROVIDERS=new Set(['square','paypal']);
const TX_STATUSES=new Set(['created','processing','requires_action','authorized','captured','declined','cancelled','failed']);

function json(data,status=200,extraHeaders={}){return new Response(JSON.stringify(data),{status,headers:{...JSON_HEADERS,...extraHeaders}});}
function clean(value,max=500){return String(value??'').trim().slice(0,max);}
function safeId(value){return clean(value,100).replace(/[^A-Za-z0-9_-]/g,'');}
function cents(value){const n=Number(value);return Number.isSafeInteger(n)&&n>0?n:null;}
function currency(value){const v=clean(value,3).toUpperCase();return /^[A-Z]{3}$/.test(v)?v:null;}
function now(){return new Date().toISOString();}
function containsRawCardData(body){
  if(!body||typeof body!=='object')return false;
  const bad=['pan','cardNumber','card_number','cvv','cvc','securityCode','security_code','track1','track2','magstripe'];
  return bad.some(k=>body[k]!==undefined&&body[k]!==null&&clean(body[k],500)!=='');
}
async function readBody(request){
  const length=Number(request.headers.get('content-length')||0);
  if(length>MAX_BODY)throw new Error('Request body too large');
  return request.json().catch(()=>({}));
}
function cookieValue(request,name){
  const raw=request.headers.get('cookie')||'';
  for(const part of raw.split(';')){const [key,...rest]=part.trim().split('=');if(key===name)return decodeURIComponent(rest.join('='));}
  return null;
}
function validOwnerToken(token){return /^[A-Za-z0-9_-]{40,160}$/.test(String(token||''));}
function newOwnerToken(){return crypto.randomUUID().replaceAll('-','')+crypto.randomUUID().replaceAll('-','');}
function ownerToken(request){
  const header=request.headers.get('authorization')||'';
  const bearer=header.startsWith('Bearer ')?header.slice(7).trim():'';
  if(validOwnerToken(bearer))return bearer;
  const cookie=cookieValue(request,OWNER_COOKIE);
  return validOwnerToken(cookie)?cookie:null;
}
function ownerCookie(token){return `${OWNER_COOKIE}=${encodeURIComponent(token)}; Path=/; Max-Age=31536000; HttpOnly; Secure; SameSite=Lax`;}
function ensureOwner(request){const existing=ownerToken(request);if(existing)return {token:existing,setCookie:null};const token=newOwnerToken();return {token,setCookie:ownerCookie(token)};}
function sameOriginWrite(request,url){
  if(['GET','HEAD','OPTIONS'].includes(request.method))return true;
  const origin=request.headers.get('origin');
  if(!origin)return true;
  try{return new URL(origin).origin===url.origin;}catch{return false;}
}
function sanitizeMethod(method){if(!method)return method;const {paymentMethodRef,...safe}=method;return safe;}
function sanitizeSnapshot(data){return {...data,methods:(data?.methods||[]).map(sanitizeMethod)};}
function envMode(value){return clean(value,20).toLowerCase()==='production'?'production':'sandbox';}
function squareBase(env){return envMode(env.SQUARE_ENVIRONMENT)==='production'?'https://connect.squareup.com':'https://connect.squareupsandbox.com';}
function paypalBase(env){return envMode(env.PAYPAL_ENVIRONMENT)==='production'?'https://api-m.paypal.com':'https://api-m.sandbox.paypal.com';}
function providerStatus(env={}){
  const squareServer=Boolean(env.SQUARE_ACCESS_TOKEN&&env.SQUARE_LOCATION_ID);
  const squareClient=Boolean(squareServer&&env.SQUARE_APPLICATION_ID);
  const paypal=Boolean(env.PAYPAL_CLIENT_ID&&env.PAYPAL_CLIENT_SECRET);
  return {
    square:{configured:squareServer,clientReady:squareClient,environment:envMode(env.SQUARE_ENVIRONMENT),applicationId:squareClient?String(env.SQUARE_APPLICATION_ID):null,locationId:squareClient?String(env.SQUARE_LOCATION_ID):null,apiVersion:env.SQUARE_API_VERSION||SQUARE_VERSION},
    paypal:{configured:paypal,clientReady:paypal,environment:envMode(env.PAYPAL_ENVIRONMENT),clientId:paypal?String(env.PAYPAL_CLIENT_ID):null}
  };
}

function defaultSnapshot(){return {methods:[],transactions:[],preferences:{applePayCompatibilityCheck:false},updatedAt:now()};}
export class WalletStore{
  constructor(state){this.state=state;}
  async snapshot(){return (await this.state.storage.get('wallet'))||defaultSnapshot();}
  async save(data){data.updatedAt=now();await this.state.storage.put('wallet',data);return data;}
  async fetch(request){
    const url=new URL(request.url),path=url.pathname;
    const data=await this.snapshot();
    if(request.method==='GET'&&path==='/snapshot')return json(data);
    if(request.method==='PATCH'&&path==='/preferences'){
      const body=await readBody(request);
      if(typeof body.applePayCompatibilityCheck!=='boolean')return json({ok:false,error:'applePayCompatibilityCheck must be boolean'},400);
      data.preferences.applePayCompatibilityCheck=body.applePayCompatibilityCheck;
      await this.save(data);return json({ok:true,preferences:data.preferences});
    }
    if(request.method==='POST'&&path==='/method'){
      const body=await readBody(request);
      if(containsRawCardData(body))return json({ok:false,error:'raw_card_data_prohibited_use_provider_tokenization'},400);
      const provider=clean(body.provider,20).toLowerCase();
      const ref=clean(body.paymentMethodRef,500);
      if(!PROVIDERS.has(provider)||!ref)return json({ok:false,error:'provider_and_tokenized_reference_required'},400);
      if(data.methods.length>=MAX_METHODS)return json({ok:false,error:'wallet_method_limit_reached'},409);
      const last4=clean(body.last4,4);if(last4&&!/^\d{4}$/.test(last4))return json({ok:false,error:'invalid_last4'},400);
      if(data.methods.some(x=>x.provider===provider&&x.paymentMethodRef===ref&&x.status==='active'))return json({ok:false,error:'payment_method_already_exists'},409);
      const item={id:crypto.randomUUID(),provider,providerMethodType:clean(body.providerMethodType,30)|| (provider==='paypal'?'paypal':'card'),paymentMethodRef:ref,brand:clean(body.brand,40)||null,last4:last4||null,nickname:clean(body.nickname,120)||null,status:'active',showHistory:true,allowNotifications:true,issuerPhone:null,issuerEmail:null,issuerUrl:null,createdAt:now(),updatedAt:now()};
      data.methods.unshift(item);await this.save(data);return json({ok:true,item},201);
    }
    if(path.startsWith('/method/')&&request.method==='PATCH'){
      const id=safeId(path.split('/').pop()),item=data.methods.find(x=>x.id===id);if(!item)return json({ok:false,error:'payment_method_not_found'},404);
      const body=await readBody(request);if(containsRawCardData(body))return json({ok:false,error:'raw_card_data_prohibited'},400);
      if(body.nickname!==undefined)item.nickname=clean(body.nickname,120)||null;
      if(body.showHistory!==undefined){if(typeof body.showHistory!=='boolean')return json({ok:false,error:'showHistory must be boolean'},400);item.showHistory=body.showHistory;}
      if(body.allowNotifications!==undefined){if(typeof body.allowNotifications!=='boolean')return json({ok:false,error:'allowNotifications must be boolean'},400);item.allowNotifications=body.allowNotifications;}
      if(body.issuerPhone!==undefined)item.issuerPhone=clean(body.issuerPhone,80)||null;
      if(body.issuerEmail!==undefined)item.issuerEmail=clean(body.issuerEmail,320)||null;
      if(body.issuerUrl!==undefined)item.issuerUrl=clean(body.issuerUrl,1000)||null;
      item.updatedAt=now();await this.save(data);return json({ok:true,item});
    }
    if(path.startsWith('/method/')&&request.method==='DELETE'){
      const id=safeId(path.split('/').pop()),item=data.methods.find(x=>x.id===id);if(!item)return json({ok:false,error:'payment_method_not_found'},404);
      item.status='inactive';item.updatedAt=now();await this.save(data);return json({ok:true,item});
    }
    if(request.method==='POST'&&path==='/transaction'){
      const body=await readBody(request),amount=cents(body.amountCents),ccy=currency(body.currency||'USD'),provider=clean(body.provider,20).toLowerCase();
      if(!amount||!ccy||!PROVIDERS.has(provider)||!clean(body.merchantName,200))return json({ok:false,error:'invalid_transaction'},400);
      const item={id:crypto.randomUUID(),paymentMethodId:safeId(body.paymentMethodId)||null,amountCents:amount,currency:ccy,merchantName:clean(body.merchantName,200),merchantReference:clean(body.merchantReference,200)||null,status:'created',provider,providerIntentRef:null,providerActionUrl:null,failureCode:null,createdAt:now(),updatedAt:now()};
      data.transactions.unshift(item);if(data.transactions.length>MAX_TRANSACTIONS)data.transactions.length=MAX_TRANSACTIONS;await this.save(data);return json({ok:true,item},201);
    }
    if(path.startsWith('/transaction/')&&request.method==='PATCH'){
      const id=safeId(path.split('/').pop()),item=data.transactions.find(x=>x.id===id);if(!item)return json({ok:false,error:'transaction_not_found'},404);
      const body=await readBody(request);const status=clean(body.status,30);if(status&&!TX_STATUSES.has(status))return json({ok:false,error:'invalid_transaction_status'},400);
      if(status)item.status=status;if(body.providerIntentRef!==undefined)item.providerIntentRef=clean(body.providerIntentRef,240)||null;if(body.providerActionUrl!==undefined)item.providerActionUrl=clean(body.providerActionUrl,1000)||null;if(body.failureCode!==undefined)item.failureCode=clean(body.failureCode,240)||null;item.updatedAt=now();await this.save(data);return json({ok:true,item});
    }
    return json({ok:false,error:'not_found'},404);
  }
}

function store(env,token){if(!env?.WALLET_STORE||!token)return null;return env.WALLET_STORE.get(env.WALLET_STORE.idFromName(token));}
async function snapshot(env,token){const stub=store(env,token);if(!stub)return null;const response=await stub.fetch('https://wallet.internal/snapshot');return response.json();}
async function internalJson(stub,path,method,body){const response=await stub.fetch(new Request(`https://wallet.internal${path}`,{method,headers:{'content-type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)}));const payload=await response.json();if(!response.ok)throw Object.assign(new Error(payload.error||'wallet_store_error'),{status:response.status,payload});return payload;}

async function squareCharge(env,{sourceId,amountCents,currencyCode,merchantName,referenceId,idempotencyKey,verificationToken}){
  if(!env.SQUARE_ACCESS_TOKEN||!env.SQUARE_LOCATION_ID)return {ok:false,httpStatus:503,status:'failed',failureCode:'square_not_configured'};
  const payment={source_id:sourceId,idempotency_key:idempotencyKey,amount_money:{amount:amountCents,currency:currencyCode},location_id:env.SQUARE_LOCATION_ID,reference_id:referenceId,note:merchantName,autocomplete:true};
  if(verificationToken)payment.verification_token=verificationToken;
  const response=await fetch(`${squareBase(env)}/v2/payments`,{method:'POST',headers:{authorization:`Bearer ${env.SQUARE_ACCESS_TOKEN}`,'content-type':'application/json','square-version':env.SQUARE_API_VERSION||SQUARE_VERSION},body:JSON.stringify(payment)});
  const payload=await response.json().catch(()=>({}));
  if(!response.ok){const e=payload?.errors?.[0]||{};return {ok:false,httpStatus:e.code==='CARD_DECLINED'?402:502,status:e.code==='CARD_DECLINED'?'declined':'failed',failureCode:e.code||'square_payment_failed',providerIntentRef:payload?.payment?.id||null};}
  const s=String(payload?.payment?.status||'').toUpperCase();const status=s==='COMPLETED'?'captured':s==='APPROVED'?'authorized':'failed';return {ok:status!=='failed',httpStatus:status==='failed'?502:200,status,providerIntentRef:payload?.payment?.id||null,failureCode:status==='failed'?'square_unexpected_status':null};
}
async function paypalAccessToken(env){
  if(!env.PAYPAL_CLIENT_ID||!env.PAYPAL_CLIENT_SECRET)throw Object.assign(new Error('paypal_not_configured'),{status:503});
  const response=await fetch(`${paypalBase(env)}/v1/oauth2/token`,{method:'POST',headers:{authorization:`Basic ${btoa(`${env.PAYPAL_CLIENT_ID}:${env.PAYPAL_CLIENT_SECRET}`)}`,'content-type':'application/x-www-form-urlencoded',accept:'application/json'},body:'grant_type=client_credentials'});const payload=await response.json().catch(()=>({}));if(!response.ok||!payload.access_token)throw Object.assign(new Error('paypal_oauth_failed'),{status:502});return payload.access_token;
}
async function paypalCreateOrder(env,tx){
  const token=await paypalAccessToken(env);const response=await fetch(`${paypalBase(env)}/v2/checkout/orders`,{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json','paypal-request-id':tx.id},body:JSON.stringify({intent:'CAPTURE',purchase_units:[{reference_id:tx.id,description:tx.merchantName,amount:{currency_code:tx.currency,value:(tx.amountCents/100).toFixed(2)}}]})});const payload=await response.json().catch(()=>({}));if(!response.ok)return {ok:false,httpStatus:response.status===422?402:502,status:'failed',failureCode:payload?.details?.[0]?.issue||payload?.name||'paypal_order_failed'};return {ok:true,httpStatus:201,status:'requires_action',providerIntentRef:payload.id};
}
async function paypalCaptureOrder(env,orderId,idempotencyKey){
  const token=await paypalAccessToken(env);const response=await fetch(`${paypalBase(env)}/v2/checkout/orders/${encodeURIComponent(orderId)}/capture`,{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json','paypal-request-id':idempotencyKey},body:'{}'});const payload=await response.json().catch(()=>({}));if(!response.ok)return {ok:false,httpStatus:response.status===422?402:502,status:'failed',failureCode:payload?.details?.[0]?.issue||payload?.name||'paypal_capture_failed',providerIntentRef:orderId};const status=String(payload?.status||'').toUpperCase()==='COMPLETED'?'captured':'failed';return {ok:status==='captured',httpStatus:status==='captured'?200:502,status,providerIntentRef:payload?.id||orderId,failureCode:status==='captured'?null:'paypal_unexpected_status'};
}
async function paypalVaultCharge(env,tx,method){
  const token=await paypalAccessToken(env);const type=method.providerMethodType==='card'?'card':'paypal';const response=await fetch(`${paypalBase(env)}/v2/checkout/orders`,{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json','paypal-request-id':tx.id},body:JSON.stringify({intent:'CAPTURE',purchase_units:[{reference_id:tx.id,description:tx.merchantName,amount:{currency_code:tx.currency,value:(tx.amountCents/100).toFixed(2)}}],payment_source:{[type]:{vault_id:method.paymentMethodRef}}})});const payload=await response.json().catch(()=>({}));if(!response.ok)return {ok:false,httpStatus:response.status===422?402:502,status:'failed',failureCode:payload?.details?.[0]?.issue||payload?.name||'paypal_order_failed',providerIntentRef:payload?.id||null};const s=String(payload?.status||'').toUpperCase();if(s==='COMPLETED')return {ok:true,httpStatus:200,status:'captured',providerIntentRef:payload.id};if(s==='APPROVED')return paypalCaptureOrder(env,payload.id,tx.id);const link=(payload?.links||[]).find(x=>x.rel==='payer-action'||x.rel==='approve');if(s==='PAYER_ACTION_REQUIRED'||s==='CREATED')return {ok:true,httpStatus:202,status:'requires_action',providerIntentRef:payload.id,actionUrl:link?.href||null};return {ok:false,httpStatus:502,status:'failed',failureCode:'paypal_unexpected_status',providerIntentRef:payload?.id||null};
}

async function api(request,env,url){
  if(url.pathname==='/api/wallet/status'&&request.method==='GET')return json({ok:true,service:'atlas-wallet',storage:Boolean(env?.WALLET_STORE),authMode:'private-device-http-only-cookie-v1',providers:providerStatus(env)});
  if(!sameOriginWrite(request,url))return json({ok:false,error:'cross_origin_write_rejected'},403);
  if(url.pathname==='/api/wallet/reset-owner'&&request.method==='POST'){const token=newOwnerToken();return json({ok:true,reset:true},200,{'set-cookie':ownerCookie(token)});}
  const token=ownerToken(request);if(!token)return json({ok:false,error:'wallet_owner_cookie_required'},401);const stub=store(env,token);if(!stub)return json({ok:false,error:'WALLET_STORE binding unavailable'},503);
  if(url.pathname==='/api/wallet/snapshot'&&request.method==='GET'){const data=await snapshot(env,token);return json(sanitizeSnapshot(data));}
  if(url.pathname==='/api/wallet/preferences'&&request.method==='PATCH'){const body=await readBody(request);return json(await internalJson(stub,'/preferences','PATCH',body));}
  if(url.pathname==='/api/wallet/payment-methods'&&request.method==='POST'){const body=await readBody(request);const result=await internalJson(stub,'/method','POST',body);return json({ok:true,item:sanitizeMethod(result.item)},201);}
  if(url.pathname.startsWith('/api/wallet/payment-methods/')&&(request.method==='PATCH'||request.method==='DELETE')){const id=safeId(url.pathname.split('/').pop());const body=request.method==='PATCH'?await readBody(request):undefined;const result=await internalJson(stub,`/method/${id}`,request.method,body);return json({ok:true,item:sanitizeMethod(result.item)});}
  if(url.pathname.startsWith('/api/wallet/payment-methods/')&&url.pathname.endsWith('/pay')&&request.method==='POST'){
    const id=safeId(url.pathname.split('/').at(-2)),data=await snapshot(env,token),method=data?.methods?.find(x=>x.id===id&&x.status==='active');if(!method)return json({ok:false,error:'payment_method_not_found_or_inactive'},404);const body=await readBody(request),amount=cents(body.amountCents),ccy=currency(body.currency||'USD'),merchantName=clean(body.merchantName,200);if(!amount||!ccy||!merchantName)return json({ok:false,error:'merchant_amount_currency_required'},400);
    const created=await internalJson(stub,'/transaction','POST',{paymentMethodId:id,amountCents:amount,currency:ccy,merchantName,merchantReference:body.merchantReference||null,provider:method.provider});const tx=created.item;await internalJson(stub,`/transaction/${tx.id}`,'PATCH',{status:'processing'});
    let result;if(method.provider==='square')result=await squareCharge(env,{sourceId:method.paymentMethodRef,amountCents:amount,currencyCode:ccy,merchantName,referenceId:tx.id,idempotencyKey:tx.id});else result=await paypalVaultCharge(env,tx,method);
    const updated=await internalJson(stub,`/transaction/${tx.id}`,'PATCH',{status:result.status,providerIntentRef:result.providerIntentRef||null,providerActionUrl:result.actionUrl||null,failureCode:result.failureCode||null});return json({ok:result.ok,transaction:updated.item,actionUrl:result.actionUrl||null},result.httpStatus|| (result.ok?200:402));
  }
  if(url.pathname==='/api/wallet/checkout/square'&&request.method==='POST'){
    const body=await readBody(request);if(containsRawCardData(body))return json({ok:false,error:'raw_card_data_prohibited'},400);const amount=cents(body.amountCents),ccy=currency(body.currency||'USD'),merchantName=clean(body.merchantName,200),sourceToken=clean(body.sourceToken,700);if(!amount||!ccy||!merchantName||!sourceToken)return json({ok:false,error:'sourceToken_merchant_amount_currency_required'},400);
    const created=await internalJson(stub,'/transaction','POST',{amountCents:amount,currency:ccy,merchantName,merchantReference:body.merchantReference||null,provider:'square'});const tx=created.item;await internalJson(stub,`/transaction/${tx.id}`,'PATCH',{status:'processing'});const result=await squareCharge(env,{sourceId:sourceToken,amountCents:amount,currencyCode:ccy,merchantName,referenceId:tx.id,idempotencyKey:tx.id,verificationToken:clean(body.verificationToken,700)||null});const updated=await internalJson(stub,`/transaction/${tx.id}`,'PATCH',{status:result.status,providerIntentRef:result.providerIntentRef||null,failureCode:result.failureCode||null});return json({ok:result.ok,transaction:updated.item},result.httpStatus|| (result.ok?200:402));
  }
  if(url.pathname==='/api/wallet/checkout/paypal/order'&&request.method==='POST'){
    const body=await readBody(request),amount=cents(body.amountCents),ccy=currency(body.currency||'USD'),merchantName=clean(body.merchantName,200);if(!amount||!ccy||!merchantName)return json({ok:false,error:'merchant_amount_currency_required'},400);const created=await internalJson(stub,'/transaction','POST',{amountCents:amount,currency:ccy,merchantName,merchantReference:body.merchantReference||null,provider:'paypal'});const tx=created.item;const result=await paypalCreateOrder(env,tx);const updated=await internalJson(stub,`/transaction/${tx.id}`,'PATCH',{status:result.status,providerIntentRef:result.providerIntentRef||null,failureCode:result.failureCode||null});return json({ok:result.ok,transaction:updated.item,orderId:result.providerIntentRef||null},result.httpStatus|| (result.ok?201:502));
  }
  const capture=url.pathname.match(/^\/api\/wallet\/checkout\/paypal\/([^/]+)\/capture$/);if(capture&&request.method==='POST'){
    const txId=safeId(capture[1]),data=await snapshot(env,token),tx=data?.transactions?.find(x=>x.id===txId&&x.provider==='paypal');if(!tx||!tx.providerIntentRef)return json({ok:false,error:'paypal_transaction_not_found'},404);await internalJson(stub,`/transaction/${tx.id}`,'PATCH',{status:'processing'});const result=await paypalCaptureOrder(env,tx.providerIntentRef,`${tx.id}-capture`);const updated=await internalJson(stub,`/transaction/${tx.id}`,'PATCH',{status:result.status,providerIntentRef:result.providerIntentRef||tx.providerIntentRef,failureCode:result.failureCode||null});return json({ok:result.ok,transaction:updated.item},result.httpStatus|| (result.ok?200:402));
  }
  return null;
}

const CSS=`:root{--bg:#eef0f5;--panel:#fff;--text:#101114;--muted:#737780;--line:#e0e2e8;--blue:#0b5cab;--green:#0b9a47;--red:#cf2434;--shadow:0 16px 44px rgba(42,46,58,.10)}*{box-sizing:border-box}body{margin:0;background:linear-gradient(#f6f7fa,#e9ebf1);color:var(--text);font-family:Inter,-apple-system,BlinkMacSystemFont,"SF Pro Display","Segoe UI",sans-serif;min-height:100vh}.shell{width:min(900px,100%);margin:auto;padding:22px 24px 60px}.top{display:grid;grid-template-columns:56px 1fr 56px;align-items:center;margin-bottom:28px}.back{width:50px;height:50px;border:1px solid #fff;background:#ffffffcc;border-radius:50%;box-shadow:var(--shadow);font-size:27px;cursor:pointer}.title{text-align:center;font-size:clamp(26px,4vw,34px);font-weight:850;letter-spacing:-.03em}.panel{background:var(--panel);border-radius:28px;box-shadow:0 1px 0 #00000008;overflow:hidden}.statusbar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}.pill{padding:7px 10px;border-radius:999px;background:#e8eaef;color:#575b64;font-size:11px;font-weight:800}.pill.live{background:#e4f7ec;color:#077639}.pill.warn{background:#fff0d2;color:#875800}.methodList{padding:5px 22px}.method{display:grid;grid-template-columns:58px 1fr auto;gap:15px;align-items:center;padding:17px 0;border-bottom:1px solid var(--line);cursor:pointer}.method:last-child{border-bottom:0}.icon{width:54px;height:43px;border:1px solid #d7d9df;border-radius:10px;background:#fff;display:grid;place-items:center;font-weight:900;font-size:12px}.icon.square{background:#111;color:#fff}.icon.paypal{color:#0565c4}.name{font-size:20px;font-weight:650}.meta{font-size:13px;color:#888c94;margin-top:3px}.chev{font-size:28px;color:#7f838a}.section{margin-top:24px}.sectionTitle{font-size:17px;color:#646870;font-weight:760;margin:0 0 9px 8px}.empty{padding:32px;text-align:center;color:var(--muted)}.linkBtn{border:0;background:transparent;color:var(--blue);padding:17px 0;font-weight:700;font-size:18px;cursor:pointer}.compat{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 20px}.hint{color:var(--muted);line-height:1.38;padding:10px 8px 0;font-size:14px}.switch{position:relative;width:62px;height:34px;flex:none}.switch input{opacity:0;width:0;height:0}.slider{position:absolute;inset:0;background:#8b8e95;border-radius:999px;transition:.18s}.slider:before{content:"";position:absolute;width:28px;height:28px;left:3px;top:3px;border-radius:50%;background:#fff;box-shadow:0 1px 4px #0003;transition:.18s}.switch input:checked+.slider{background:var(--green)}.switch input:checked+.slider:before{transform:translateX(28px)}.detailHero{text-align:center;padding:8px 10px 10px}.cardArt{width:220px;height:132px;margin:0 auto 17px;border-radius:17px;background:linear-gradient(135deg,#0b1830,#214372 60%,#79a9ca);color:white;padding:17px;text-align:left;display:flex;flex-direction:column;justify-content:space-between;box-shadow:0 13px 34px #18334c38}.cardArt.square{background:linear-gradient(135deg,#111,#444)}.cardArt.paypal{background:linear-gradient(135deg,#073887,#0780de)}.detailName{font-size:33px;font-weight:850;letter-spacing:-.035em}.detailType{font-size:18px;color:var(--muted);margin-top:3px}.quick{display:flex;justify-content:center;gap:18px;margin:20px 0}.round{width:56px;height:56px;border:0;border-radius:50%;background:#d9dbe1;font-size:22px;cursor:pointer}.round:disabled{opacity:.34}.tabs{display:grid;grid-template-columns:1fr 1fr;background:#d7d9df;border-radius:999px;padding:3px;margin:22px 0}.tab{border:0;background:transparent;border-radius:999px;padding:10px;font-weight:780;cursor:pointer}.tab.on{background:#fff}.settings{padding:5px 20px}.setting{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:15px 0;border-bottom:1px solid var(--line)}.setting:last-child{border-bottom:0}.transactions{padding:2px 20px 10px}.tx{display:grid;grid-template-columns:1fr auto;gap:12px;padding:16px 0;border-bottom:1px solid var(--line)}.merchant{font-size:18px;font-weight:760}.txmeta{font-size:13px;color:var(--muted);margin-top:2px}.declined,.failed{color:var(--red)}.captured,.authorized{color:var(--green)}.amount{text-align:right;font-weight:760}.form{padding:18px 20px;display:grid;gap:11px}.field{display:grid;gap:5px}.field span{font-size:12px;color:var(--muted);font-weight:750}.field input,.field select{border:1px solid #d9dbe1;background:#fafbfc;border-radius:13px;padding:11px 12px;font:inherit;width:100%}.row{display:flex;gap:9px;flex-wrap:wrap}.btn{border:0;border-radius:13px;padding:11px 15px;font-weight:800;cursor:pointer}.btn.primary{background:#111318;color:#fff}.btn.secondary{background:#e8e9ee}.btn.danger{background:#ffe6e9;color:#a61223}.message{font-size:13px;color:var(--muted);min-height:18px}.message.error{color:var(--red)}.message.success{color:var(--green)}.checkoutGrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.checkoutActions{display:flex;gap:10px;flex-wrap:wrap}.applePay{display:none;background:#000;color:#fff;border:0;border-radius:10px;padding:11px 22px;font-size:20px;min-width:160px;cursor:pointer}.applePay.ready{display:inline-block}.squareBox{border:1px solid var(--line);border-radius:14px;padding:14px;background:#fafbfc}.squareBox.hidden{display:none}.paypalBox{min-height:48px}.secureNote{font-size:12px;color:#636771;background:#f2f3f6;border-radius:12px;padding:11px 12px}.hidden{display:none!important}.ownerNote{font-size:11px;color:#81858c;text-align:center;margin:14px 0}.modal{position:fixed;inset:0;background:#15172066;display:grid;place-items:end center;padding:18px;z-index:30}.sheet{width:min(680px,100%);background:white;border-radius:28px 28px 18px 18px;padding:22px;box-shadow:0 20px 80px #0004}.sheet h2{margin:0 0 8px}.sheet p{color:var(--muted);line-height:1.4}.checkoutPanel{margin-top:24px}.spinner{display:inline-block;width:16px;height:16px;border:2px solid #bbb;border-top-color:#111;border-radius:50%;animation:spin .7s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:620px){.shell{padding:16px 17px 44px}.top{grid-template-columns:50px 1fr 50px}.title{font-size:26px}.panel{border-radius:25px}.checkoutGrid{grid-template-columns:1fr}.method{grid-template-columns:52px 1fr auto}.icon{width:48px;height:39px}.name{font-size:17px}.detailName{font-size:29px}}`;

const CLIENT=`const state={snapshot:null,status:null,selected:null,squarePayments:null,squareCard:null,applePay:null,appleFingerprint:'',appleSupported:false,appleTimer:null,paypalRendered:false};const $=s=>document.querySelector(s);const all=s=>[...document.querySelectorAll(s)];function esc(v=''){return String(v).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]))}async function req(path,options={}){const r=await fetch(path,{cache:'no-store',credentials:'same-origin',...options,headers:{'content-type':'application/json',...(options.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok||d.ok===false){const e=new Error(d.error||'Request failed');e.status=r.status;e.data=d;throw e}return d}function msg(text='',kind=''){const el=$('#message');el.textContent=text;el.className='message '+kind}function money(cents,currency='USD'){try{return new Intl.NumberFormat(undefined,{style:'currency',currency}).format(Number(cents||0)/100)}catch{return '$'+(Number(cents||0)/100).toFixed(2)}}function date(v){try{return new Intl.DateTimeFormat(undefined,{month:'numeric',day:'numeric',year:'2-digit'}).format(new Date(v))}catch{return v||''}}function methodName(m){return m.nickname||m.brand||(m.provider==='paypal'?'PayPal':'Square Card')}function last4(m){return m.last4?'•••• '+m.last4:'Tokenized reference'}function providerPills(){const root=$('#providerStatus');root.innerHTML='';for(const [key,p] of Object.entries(state.status.providers||{})){root.insertAdjacentHTML('beforeend','<span class="pill '+(p.configured?'live':'warn')+'">'+esc(key==='square'?'Square':'PayPal')+' · '+(p.configured?'configured':'setup required')+' · '+esc(p.environment)+'</span>')}}function renderList(){const root=$('#methodRows'),methods=state.snapshot.methods||[];root.innerHTML=methods.length?'':'<div class="empty">No tokenized cards are stored on this private device profile yet.</div>';for(const m of methods){root.insertAdjacentHTML('beforeend','<div class="method" data-id="'+esc(m.id)+'"><div class="icon '+esc(m.provider)+'">'+esc(m.provider==='paypal'?'PayPal':m.brand||'SQ')+'</div><div><div class="name">'+esc(methodName(m))+'</div><div class="meta">'+esc(last4(m))+' · '+esc(m.provider)+' · '+esc(m.status)+'</div></div><div class="chev">›</div></div>')}all('.method').forEach(el=>el.onclick=()=>openMethod(el.dataset.id));$('#compat').checked=!!state.snapshot.preferences?.applePayCompatibilityCheck;compatibility()}function compatibility(){const enabled=$('#compat').checked;if(!enabled){$('#compatHint').textContent='Compatibility checks are off.';return}const apple=state.appleSupported;const square=state.status?.providers?.square;$('#compatHint').textContent=(apple?'Apple Pay is available on this device/browser. ':'Apple Pay was not detected on this device/browser. ')+(square?.clientReady?'Square client configuration is present. Production still requires Apple Pay domain registration.':'Square Apple Pay setup is not configured yet.')}async function load(){const [status,snapshot]=await Promise.all([fetch('/api/wallet/status',{cache:'no-store',credentials:'same-origin'}).then(r=>r.json()),req('/api/wallet/snapshot')]);state.status=status;state.snapshot=snapshot;providerPills();renderList();await setupCheckout();const card=new URL(location.href).searchParams.get('card');if(card&&(snapshot.methods||[]).some(x=>x.id===card))openMethod(card,false);else showList(false)}function showList(push=true){state.selected=null;$('#listView').classList.remove('hidden');$('#detailView').classList.add('hidden');if(push){const u=new URL(location.href);u.searchParams.delete('card');history.pushState({},'',u)}}function openMethod(id,push=true){const m=(state.snapshot.methods||[]).find(x=>x.id===id);if(!m)return;state.selected=m;$('#listView').classList.add('hidden');$('#detailView').classList.remove('hidden');$('#cardArt').className='cardArt '+m.provider;$('#cardBrand').textContent=m.brand||m.provider;$('#cardDigits').textContent=last4(m);$('#detailName').textContent=methodName(m);$('#detailType').textContent=(m.provider==='paypal'?'PayPal':'Square')+' · '+m.status;$('#nickname').value=m.nickname||'';$('#issuerPhone').value=m.issuerPhone||'';$('#issuerEmail').value=m.issuerEmail||'';$('#issuerUrl').value=m.issuerUrl||'';$('#showHistory').checked=m.showHistory!==false;$('#notify').checked=m.allowNotifications!==false;setIssuerActions(m);renderTransactions();if(push){const u=new URL(location.href);u.searchParams.set('card',id);history.pushState({id},'',u)}}function setIssuerActions(m){const phone=m.issuerPhone,email=m.issuerEmail,url=normalizeUrl(m.issuerUrl);$('#call').disabled=!phone;$('#email').disabled=!email;$('#web').disabled=!url;$('#call').onclick=phone?()=>location.href='tel:'+phone:null;$('#email').onclick=email?()=>location.href='mailto:'+email:null;$('#web').onclick=url?()=>window.open(url,'_blank','noopener'):null}function normalizeUrl(v){if(!v)return null;try{return new URL(v).href}catch{try{return new URL('https://'+v).href}catch{return null}}}function renderTransactions(){const root=$('#txRows');if(!state.selected?.showHistory){root.innerHTML='<div class="empty">Transaction history is hidden for this card.</div>';return}const rows=(state.snapshot.transactions||[]).filter(x=>x.paymentMethodId===state.selected.id);root.innerHTML=rows.length?'':'<div class="empty">No ATLAS Wallet transactions for this card.</div>';for(const tx of rows){root.insertAdjacentHTML('beforeend','<div class="tx"><div><div class="merchant">'+esc(tx.merchantName)+'</div><div class="txmeta '+esc(tx.status)+'">'+esc(tx.status.replaceAll('_',' '))+' · '+esc(date(tx.createdAt))+'</div></div><div class="amount">'+esc(money(tx.amountCents,tx.currency))+'</div></div>')}}async function patchMethod(patch){if(!state.selected)return;const d=await req('/api/wallet/payment-methods/'+encodeURIComponent(state.selected.id),{method:'PATCH',body:JSON.stringify(patch)});const idx=state.snapshot.methods.findIndex(x=>x.id===d.item.id);state.snapshot.methods[idx]=d.item;state.selected=d.item;renderList();openMethod(d.item.id,false);return d.item}async function saveInfo(){msg('Saving…');try{await patchMethod({nickname:$('#nickname').value,issuerPhone:$('#issuerPhone').value,issuerEmail:$('#issuerEmail').value,issuerUrl:$('#issuerUrl').value});msg('Saved.','success')}catch(e){msg(e.message,'error')}}async function paySaved(){if(!state.selected)return;const merchant=$('#savedMerchant').value.trim(),amount=Math.round(Number($('#savedAmount').value)*100);if(!merchant||!amount){msg('Enter a merchant and amount.','error');return}msg('Processing…');try{const d=await req('/api/wallet/payment-methods/'+encodeURIComponent(state.selected.id)+'/pay',{method:'POST',body:JSON.stringify({merchantName:merchant,amountCents:amount,currency:'USD'})});await refreshSnapshot();if(d.actionUrl)window.open(d.actionUrl,'_blank','noopener');msg('Payment status: '+d.transaction.status,d.transaction.status==='captured'?'success':'')}catch(e){await refreshSnapshot();msg((e.data?.transaction?.status||'Payment failed')+(e.data?.transaction?.failureCode?' · '+e.data.transaction.failureCode:''),'error')}}async function refreshSnapshot(){state.snapshot=await req('/api/wallet/snapshot');renderList();if(state.selected){const id=state.selected.id;const m=state.snapshot.methods.find(x=>x.id===id);if(m){state.selected=m;openMethod(id,false)}}renderAllTransactions()}function renderAllTransactions(){const root=$('#allTransactions');if(!root)return;const rows=state.snapshot.transactions||[];root.innerHTML=rows.length?'':'<div class="empty">No purchases yet.</div>';for(const tx of rows.slice(0,100)){root.insertAdjacentHTML('beforeend','<div class="tx"><div><div class="merchant">'+esc(tx.merchantName)+'</div><div class="txmeta '+esc(tx.status)+'">'+esc(tx.provider)+' · '+esc(tx.status.replaceAll('_',' '))+' · '+esc(date(tx.createdAt))+'</div></div><div class="amount">'+esc(money(tx.amountCents,tx.currency))+'</div></div>')}}function checkoutValues(){const merchant=$('#merchant').value.trim(),amount=Math.round(Number($('#amount').value)*100);if(!merchant||!amount||amount<1)throw new Error('Enter a merchant and amount greater than $0.');return {merchant,amount}}function checkoutFingerprint(v){return v.merchant+'|'+v.amount+'|USD'}async function loadScript(src,id){if(document.getElementById(id))return new Promise((resolve,reject)=>{const e=document.getElementById(id);if(e.dataset.ready==='1')resolve();else{e.addEventListener('load',resolve,{once:true});e.addEventListener('error',reject,{once:true})}});return new Promise((resolve,reject)=>{const s=document.createElement('script');s.id=id;s.src=src;s.onload=()=>{s.dataset.ready='1';resolve()};s.onerror=reject;document.head.append(s)})}async function prepareApplePay(){if(!state.appleSupported||!state.squarePayments)return;try{const v=checkoutValues(),fp=checkoutFingerprint(v);if(state.applePay&&state.appleFingerprint===fp)return;$('#applePay').classList.remove('ready');state.applePay=null;const request=state.squarePayments.paymentRequest({countryCode:'US',currencyCode:'USD',total:{amount:(v.amount/100).toFixed(2),label:v.merchant}});state.applePay=await state.squarePayments.applePay(request);state.appleFingerprint=fp;$('#applePay').classList.add('ready');$('#squareStatus').textContent='Apple Pay ready for the current amount.'}catch{state.applePay=null;state.appleFingerprint='';$('#applePay').classList.remove('ready')}}function scheduleApple(){if(!state.appleSupported)return;state.applePay=null;state.appleFingerprint='';$('#applePay').classList.remove('ready');clearTimeout(state.appleTimer);state.appleTimer=setTimeout(()=>prepareApplePay(),250)}async function setupCheckout(){const sq=state.status.providers?.square;if(sq?.clientReady){try{await loadScript(sq.environment==='production'?'https://web.squarecdn.com/v1/square.js':'https://sandbox.web.squarecdn.com/v1/square.js','squareSdk');state.squarePayments=Square.payments(sq.applicationId,sq.locationId);state.squareCard=await state.squarePayments.card();await state.squareCard.attach('#squareCard');$('#squareArea').classList.remove('hidden');state.appleSupported=typeof ApplePaySession!=='undefined'&&(()=>{try{return ApplePaySession.canMakePayments()}catch{return false}})();if(state.appleSupported){$('#merchant').addEventListener('input',scheduleApple);$('#amount').addEventListener('input',scheduleApple);scheduleApple()}compatibility()}catch(e){$('#squareStatus').textContent='Square client could not initialize: '+e.message}}const pp=state.status.providers?.paypal;if(pp?.clientReady){try{await loadScript('https://www.paypal.com/sdk/js?client-id='+encodeURIComponent(pp.clientId)+'&currency=USD&intent=capture','paypalSdk');renderPayPal()}catch(e){$('#paypalStatus').textContent='PayPal client could not initialize: '+e.message}}renderAllTransactions()}async function squareTokenPay(sourceToken,verificationToken=null,values=null){const v=values||checkoutValues();msg('Processing Square payment…');const d=await req('/api/wallet/checkout/square',{method:'POST',body:JSON.stringify({sourceToken,verificationToken:verificationToken||undefined,merchantName:v.merchant,amountCents:v.amount,currency:'USD'})});await refreshSnapshot();msg('Square payment: '+d.transaction.status,d.transaction.status==='captured'?'success':'');return d}async function paySquareCard(){try{const v=checkoutValues();const verificationDetails={amount:(v.amount/100).toFixed(2),billingContact:{},currencyCode:'USD',intent:'CHARGE',customerInitiated:true,sellerKeyedIn:false};const result=await state.squareCard.tokenize(verificationDetails);if(result.status!=='OK')throw new Error(result.errors?.map(x=>x.message).join(', ')||'Card tokenization failed');await squareTokenPay(result.token,null,v)}catch(e){msg(e.data?.transaction?.failureCode||e.message,'error')}}async function payApple(){try{const v=checkoutValues(),fp=checkoutFingerprint(v);if(!state.applePay||state.appleFingerprint!==fp){msg('Apple Pay is preparing the current amount. Tap again when the Apple Pay button reappears.');scheduleApple();return}const result=await state.applePay.tokenize();if(result.status!=='OK')throw new Error(result.errors?.map(x=>x.message).join(', ')||'Apple Pay tokenization failed');let verificationToken=null;const verification=await state.squarePayments.verifyBuyer(result.token,{amount:(v.amount/100).toFixed(2),billingContact:{},currencyCode:'USD',intent:'CHARGE'});verificationToken=verification?.token||null;await squareTokenPay(result.token,verificationToken,v);scheduleApple()}catch(e){msg(e.data?.transaction?.failureCode||e.message,'error')}}function renderPayPal(){if(state.paypalRendered||!window.paypal)return;state.paypalRendered=true;paypal.Buttons({style:{layout:'horizontal',shape:'pill'},createOrder:async()=>{const {merchant,amount}=checkoutValues();const d=await req('/api/wallet/checkout/paypal/order',{method:'POST',body:JSON.stringify({merchantName:merchant,amountCents:amount,currency:'USD'})});window.__atlasPaypalTx=d.transaction.id;return d.orderId},onApprove:async()=>{const tx=window.__atlasPaypalTx;if(!tx)throw new Error('ATLAS PayPal transaction missing');const d=await req('/api/wallet/checkout/paypal/'+encodeURIComponent(tx)+'/capture',{method:'POST',body:'{}'});await refreshSnapshot();msg('PayPal payment: '+d.transaction.status,d.transaction.status==='captured'?'success':'')},onError:e=>msg('PayPal: '+(e.message||e),'error')}).render('#paypalButtons')}async function addMethod(){const provider=$('#newProvider').value,ref=$('#newRef').value.trim(),last=$('#newLast4').value.trim();if(!ref){$('#addMsg').textContent='A provider token or vaulted reference is required.';return}if(last&&!/^\d{4}$/.test(last)){ $('#addMsg').textContent='Last 4 must contain exactly four digits.';return}try{await req('/api/wallet/payment-methods',{method:'POST',body:JSON.stringify({provider,paymentMethodRef:ref,providerMethodType:provider==='paypal'?$('#newPayPalType').value:'card',nickname:$('#newNickname').value,brand:$('#newBrand').value,last4:last||undefined})});$('#addModal').classList.add('hidden');await refreshSnapshot()}catch(e){$('#addMsg').textContent=e.message}}document.addEventListener('click',e=>{if(e.target.matches('[data-tab]')){const tab=e.target.dataset.tab;all('[data-tab]').forEach(x=>x.classList.toggle('on',x.dataset.tab===tab));$('#infoPane').classList.toggle('hidden',tab!=='info');$('#txPane').classList.toggle('hidden',tab!=='transactions')}});$('#back').onclick=()=>state.selected?showList():location.assign('/dashboard');$('#compat').onchange=async()=>{try{const d=await req('/api/wallet/preferences',{method:'PATCH',body:JSON.stringify({applePayCompatibilityCheck:$('#compat').checked})});state.snapshot.preferences=d.preferences;compatibility()}catch(e){$('#compat').checked=!$('#compat').checked}};$('#saveInfo').onclick=saveInfo;$('#showHistory').onchange=()=>patchMethod({showHistory:$('#showHistory').checked}).catch(e=>msg(e.message,'error'));$('#notify').onchange=()=>patchMethod({allowNotifications:$('#notify').checked}).catch(e=>msg(e.message,'error'));$('#deactivate').onclick=async()=>{if(!state.selected)return;try{await req('/api/wallet/payment-methods/'+encodeURIComponent(state.selected.id),{method:'DELETE'});await refreshSnapshot();showList()}catch(e){msg(e.message,'error')}};$('#paySaved').onclick=paySaved;$('#addMethod').onclick=()=>$('#addModal').classList.remove('hidden');$('#closeAdd').onclick=()=>$('#addModal').classList.add('hidden');$('#saveAdd').onclick=addMethod;$('#newProvider').onchange=()=>$('#paypalTypeField').classList.toggle('hidden',$('#newProvider').value!=='paypal');$('#squarePay').onclick=paySquareCard;$('#applePay').onclick=payApple;$('#resetWallet').onclick=async()=>{if(confirm('Reset this device wallet profile? Existing server data will remain isolated under the previous device key.')){try{await req('/api/wallet/reset-owner',{method:'POST',body:'{}'});location.reload()}catch(e){msg(e.message,'error')}}};window.addEventListener('popstate',()=>{const id=new URL(location.href).searchParams.get('card');if(id)openMethod(id,false);else showList(false)});load().catch(e=>msg(e.message,'error'));`;

function html(){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#eef0f5"><title>ATLAS Wallet</title><style>${CSS}</style></head><body><main class="shell"><header class="top"><button id="back" class="back" aria-label="Back">‹</button><div class="title">ATLAS Wallet</div><div></div></header><div id="message" class="message"></div><section id="listView"><div id="providerStatus" class="statusbar"></div><div class="panel methodList"><div id="methodRows"></div><button id="addMethod" class="linkBtn">Add Card</button></div><div class="section"><div class="panel compat"><span>Apple Pay Compatibility</span><label class="switch"><input id="compat" type="checkbox"><span class="slider"></span></label></div><div id="compatHint" class="hint">Compatibility checks are off.</div></div><section class="panel form checkoutPanel"><div><strong>Buy with ATLAS Pay</strong><div class="meta">Secure provider checkout. ATLAS never receives raw card numbers or CVV.</div></div><div class="checkoutGrid"><label class="field"><span>Merchant</span><input id="merchant" maxlength="200" placeholder="Merchant name"></label><label class="field"><span>Amount (USD)</span><input id="amount" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="0.00"></label></div><div id="squareArea" class="squareBox hidden"><div class="meta">Square secure card form</div><div id="squareCard"></div><div class="checkoutActions"><button id="squarePay" class="btn primary">Pay by card</button><button id="applePay" class="applePay"> Pay</button></div><div id="squareStatus" class="meta"></div></div><div id="paypalButtons" class="paypalBox"></div><div id="paypalStatus" class="meta"></div><div class="secureNote">Apple Pay through Square requires a valid Square application/location, HTTPS and Apple Pay domain registration. Square buyer verification is applied before the server charge. PayPal requires server credentials. Missing provider configuration fails closed; no payment is simulated.</div></section><div class="section"><div class="sectionTitle">Latest Transactions</div><div id="allTransactions" class="panel transactions"></div></div><div class="ownerNote">Private device wallet profile · isolated by an HttpOnly device cookie until canonical ATLAS account identity is bound to Wallet.</div><div style="text-align:center"><button id="resetWallet" class="btn secondary">Reset device wallet profile</button></div></section><section id="detailView" class="hidden"><div class="detailHero"><div id="cardArt" class="cardArt"><div style="font-size:11px;opacity:.7">ATLAS Wallet</div><div><div id="cardBrand"></div><div id="cardDigits" style="letter-spacing:.14em;font-weight:750"></div></div></div><div id="detailName" class="detailName"></div><div id="detailType" class="detailType"></div><div class="quick"><button id="call" class="round" title="Call issuer">☎</button><button id="email" class="round" title="Email issuer">✉</button><button id="web" class="round" title="Issuer website">↗</button></div></div><div class="tabs"><button class="tab on" data-tab="info">Info</button><button class="tab" data-tab="transactions">Transactions</button></div><div id="infoPane"><div class="panel form"><label class="field"><span>Card name</span><input id="nickname" maxlength="120"></label><label class="field"><span>Issuer phone</span><input id="issuerPhone" maxlength="80"></label><label class="field"><span>Issuer email</span><input id="issuerEmail" type="email" maxlength="320"></label><label class="field"><span>Issuer website</span><input id="issuerUrl" type="url" maxlength="1000" placeholder="https://"></label><div class="row"><button id="saveInfo" class="btn primary">Save</button><button id="deactivate" class="btn danger">Deactivate card</button></div></div></div><div id="txPane" class="hidden"><div class="section"><div class="panel settings"><div class="setting"><span>Show History</span><label class="switch"><input id="showHistory" type="checkbox"><span class="slider"></span></label></div><div class="setting"><span>Allow Notifications</span><label class="switch"><input id="notify" type="checkbox"><span class="slider"></span></label></div></div><div class="hint">This preference is stored. Background push notifications are not represented as active unless a notification delivery service is configured.</div></div><div class="section"><div class="sectionTitle">Latest Transactions</div><div id="txRows" class="panel transactions"></div></div><div class="section"><div class="panel form"><strong>New purchase with this saved provider reference</strong><div class="checkoutGrid"><label class="field"><span>Merchant</span><input id="savedMerchant" maxlength="200"></label><label class="field"><span>Amount (USD)</span><input id="savedAmount" type="number" min="0.01" step="0.01"></label></div><button id="paySaved" class="btn primary">Pay with this card</button></div></div></div></section></main><div id="addModal" class="modal hidden"><div class="sheet"><h2>Add tokenized card</h2><p>ATLAS can save provider-issued references only. It cannot import or read card numbers from iPhone AutoFill. For immediate checkout, use the Square secure card form, Apple Pay, or PayPal above.</p><div class="secureNote">Never paste a full card number, CVV/CVC, magnetic-stripe data, or a payment-provider secret here. Saved provider references stay server-side and are not returned by the Wallet API.</div><div class="form"><label class="field"><span>Provider</span><select id="newProvider"><option value="square">Square</option><option value="paypal">PayPal</option></select></label><label id="paypalTypeField" class="field hidden"><span>PayPal method type</span><select id="newPayPalType"><option value="paypal">PayPal wallet vault</option><option value="card">Vaulted card</option></select></label><label class="field"><span>Provider token / vaulted reference</span><input id="newRef" autocomplete="off"></label><label class="field"><span>Card name</span><input id="newNickname" maxlength="120"></label><div class="checkoutGrid"><label class="field"><span>Brand</span><input id="newBrand" maxlength="40" placeholder="Visa"></label><label class="field"><span>Last 4</span><input id="newLast4" maxlength="4" inputmode="numeric"></label></div><div class="row"><button id="saveAdd" class="btn primary">Add Card</button><button id="closeAdd" class="btn secondary">Cancel</button></div><div id="addMsg" class="message"></div></div></div></div><script>${CLIENT}</script></body></html>`;}

export async function handleWallet(request,env,ctx){
  const url=new URL(request.url);
  if(url.pathname.startsWith('/api/wallet/'))return api(request,env,url);
  if(url.pathname==='/wallet'||url.pathname==='/wallet/'||url.pathname.startsWith('/wallet/card/')){
    const owner=ensureOwner(request),headers=new Headers(HTML_HEADERS);if(owner.setCookie)headers.set('set-cookie',owner.setCookie);return new Response(html(),{headers});
  }
  return null;
}
